        format: 2,
        content: 'I found three relevant papers.',
        parts: [
          {
            type: 'tool-invocation',
            toolInvocation: {
              state: 'result',
              toolCallId: 'call-1',
              toolName: 'search_papers',
              args: { query: 'attention mechanisms' },
              result: { papers: ['paper-1', 'paper-2', 'paper-3'] },
            },
          },
        ],
      },
      createdAt: new Date(),
    },
