### Describe the Bug

我使用mastra访问本地Qwen3.6-27B模型，当使用workspace功能时，请求报错：system message must be at the beginning.
和 #14384 是一个问题。

### Steps To Reproduce

以下是可以复现该问题的代码：
```
/**
 * Bug 复现文件: "System message must be at the beginning"
 *
 * 此文件集中了 weatherAgent 的所有初始化代码，用于向 Mastra 官方提交 bug 报告。
 * 运行方式: npx tsx reproduce-bug.ts
 */

import { Agent } from "@mastra/core/agent";
import { Memory } from "@mastra/memory";
import { Mastra } from "@mastra/core/mastra";
import { PinoLogger } from "@mastra/loggers";
import { LibSQLStore } from "@mastra/libsql";
import { createTool } from "@mastra/core/tools";
import { Workspace, LocalFilesystem, LocalSandbox } from "@mastra/core/workspace";
import { z } from "zod";
import path from "path";

// ===================== 配置 =====================

const AI_BASE_URL = process.env.AI_BASE_URL || "https://qwen.example.com.cn/v1";
const AI_MODEL_NAME = process.env.AI_MODEL_NAME || "/Qwen/Qwen3.6-27B";
const AI_API_KEY = process.env.AI_API_KEY || "your-api-key-here";

// ===================== Tool 定义 =====================

interface GeocodingResponse {
  results: {
    latitude: number;
    longitude: number;
    name: string;
  }[];
}

interface WeatherResponse {
  current: {
    time: string;
    temperature_2m: number;
    apparent_temperature: number;
    relative_humidity_2m: number;
    wind_speed_10m: number;
    wind_gusts_10m: number;
    weather_code: number;
  };
}

const weatherTool = createTool({
  id: "get-weather",
  description: "Get current weather for a location",
  inputSchema: z.object({
    location: z.string().describe("City name"),
  }),
  outputSchema: z.object({
    temperature: z.number(),
    feelsLike: z.number(),
    humidity: z.number(),
    windSpeed: z.number(),
    windGust: z.number(),
    conditions: z.string(),
    location: z.string(),
  }),
  execute: async (inputData) => {
    const location = inputData.location;

    const geocodingUrl = `https://geocoding-api.open-meteo.com/v1/search?name=${encodeURIComponent(location)}&count=1`;
    const geocodingResponse = await fetch(geocodingUrl);
    const geocodingData = (await geocodingResponse.json()) as GeocodingResponse;

    if (!geocodingData.results?.[0]) {
      throw new Error(`Location '${location}' not found`);
    }

    const { latitude, longitude, name } = geocodingData.results[0];

    const weatherUrl = `https://api.open-meteo.com/v1/forecast?latitude=${latitude}&longitude=${longitude}&current=temperature_2m,apparent_temperature,relative_humidity_2m,wind_speed_10m,wind_gusts_10m,weather_code`;

    const response = await fetch(weatherUrl);
    const data = (await response.json()) as WeatherResponse;

    return {
      temperature: data.current.temperature_2m,
      feelsLike: data.current.apparent_temperature,
      humidity: data.current.relative_humidity_2m,
      windSpeed: data.current.wind_speed_10m,
      windGust: data.current.wind_gusts_10m,
      conditions: getWeatherCondition(data.current.weather_code),
      location: name,
    };
  },
});

function getWeatherCondition(code: number): string {
  const conditions: Record<number, string> = {
    0: "Clear sky",
    1: "Mainly clear",
    2: "Partly cloudy",
    3: "Overcast",
    45: "Foggy",
    48: "Depositing rime fog",
    51: "Light drizzle",
    53: "Moderate drizzle",
    55: "Dense drizzle",
    56: "Light freezing drizzle",
    57: "Dense freezing drizzle",
    61: "Slight rain",
    63: "Moderate rain",
    65: "Heavy rain",
    66: "Light freezing rain",
    67: "Heavy freezing rain",
    71: "Slight snow fall",
    73: "Moderate snow fall",
    75: "Heavy snow fall",
    77: "Snow grains",
    80: "Slight rain showers",
    81: "Moderate rain showers",
    82: "Violent rain showers",
    85: "Slight snow showers",
    86: "Heavy snow showers",
    95: "Thunderstorm",
    96: "Thunderstorm with slight hail",
    99: "Thunderstorm with heavy hail",
  };
  return conditions[code] || "Unknown";
}

// ===================== Workspace 定义 =====================

const workspaceDir = path.join(process.cwd(), "workspace");

const workspace = new Workspace({
  id: "project-workspace",
  name: "Project Workspace",
  filesystem: new LocalFilesystem({
    basePath: workspaceDir,
    contained: true,
  }),
  sandbox: new LocalSandbox({
    workingDirectory: workspaceDir,
  }),
});

// ===================== Agent 定义 =====================

const weatherAgent = new Agent({
  id: "weather-agent",
  name: "Weather Agent",
  instructions: `
      You are a helpful weather assistant that provides accurate weather information and can help planning activities based on the weather.

      Your primary function is to help users get weather details for specific locations. When responding:
      - Always ask for a location if none is provided
      - If the location name isn't in English, please translate it
      - If giving a location with multiple parts (e.g. "New York, NY"), use the most relevant part (e.g. "New York")
      - Include relevant details like humidity, wind conditions, and precipitation
      - Keep responses concise but informative
      - If the user asks for activities and provides the weather forecast, suggest activities based on the weather forecast.
      - If the user asks for activities, respond in the format they request.

      Use the weatherTool to fetch current weather data.
`,
  model: {
    url: AI_BASE_URL,
    id: `alibaba/${AI_MODEL_NAME}`,
    apiKey: AI_API_KEY,
  },
  defaultOptions: {
    modelSettings: {
      temperature: 0.7,
      topP: 0.8,
      topK: 20,
      presencePenalty: 1.5,
    },
  },
  tools: { weatherTool },
  workspace,
  memory: new Memory(),
});

// ===================== Mastra 实例 =====================

const mastra = new Mastra({
  agents: { weatherAgent },
  storage: new LibSQLStore({
    id: "mastra-storage",
    url: "file:./mastra.db",
  }),
  logger: new PinoLogger({
    name: "Mastra",
    level: "info",
  }),
});

// ===================== Bug 复现逻辑 =====================

async function reproduce() {
  console.log("开始复现 bug: System message must be at the beginning\n");

  const agent = mastra.getAgent("weatherAgent");
  const memory = agent.getMemory();

  const THREAD_ID = "test-thread-id";
  const RESOURCE_ID = "test-resource-id";

  // 第一次对话
  console.log("=== 第一次对话 ===");
  try {
    const stream1 = await agent.stream([
      { role: "user", content: "北京今天天气怎么样？" },
    ], {
      threadId: THREAD_ID,
      resourceId: RESOURCE_ID,
    });

    let text1 = "";
    for await (const chunk of stream1.textStream) {
      text1 += chunk;
    }
    console.log("第一次对话成功:", text1.slice(0, 100) + "...");
  } catch (e) {
    console.error("第一次对话失败:", e);
  }

  // 第二次对话（使用 memory）
  console.log("\n=== 第二次对话（带历史消息） ===");
  try {
    const stream2 = await agent.stream([
      { role: "user", content: "明天呢？" },
    ], {
      threadId: THREAD_ID,
      resourceId: RESOURCE_ID,
    });

    let text2 = "";
    for await (const chunk of stream2.textStream) {
      text2 += chunk;
    }
    console.log("第二次对话成功:", text2.slice(0, 100) + "...");
  } catch (e) {
    console.error("第二次对话失败:", e);
  }
}

reproduce().catch(console.error);

