comments.body:
I solved it by creating an input processor for the supervisor agent.

Implemented a processInputStep function that iterates over all messages, and removes the subAgentToolResults

```
import type {
  Processor,
  ProcessInputArgs,
  ProcessInputResult,
  ProcessInputStepArgs,
  ProcessInputStepResult,
} from '@mastra/core/processors'
import type { MastraDBMessage } from '@mastra/core/memory'

const PROCESSOR_ID = 'strip-subagent-tool-results-from-context' as const
const SUB_AGENT_TOOL_RESULTS_KEY = 'subAgentToolResults'

const UNCHANGED = Symbol('unchanged')
type Unchanged = typeof UNCHANGED

function isPlainObject(v: unknown): v is Record<string, unknown> {
  if (typeof v !== 'object' || v === null || Array.isArray(v)) return false
  const proto = Object.getPrototypeOf(v)
  return proto === Object.prototype || proto === null
}

function stripSubAgentToolResults(value: unknown): unknown | Unchanged {
  if (Array.isArray(value)) {
    let changed = false
    const next: unknown[] = new Array(value.length)
    for (let i = 0; i < value.length; i++) {
      const r = stripSubAgentToolResults(value[i])
      if (r === UNCHANGED) {
        next[i] = value[i]
      } else {
        next[i] = r
        changed = true
      }
    }
    return changed ? next : UNCHANGED
  }

  if (!isPlainObject(value)) return UNCHANGED

  let next: Record<string, unknown> | undefined
  for (const [key, raw] of Object.entries(value)) {
    if (key === SUB_AGENT_TOOL_RESULTS_KEY) {
      const alreadyEmpty = Array.isArray(raw) && raw.length === 0
      if (!alreadyEmpty) {
        next ??= { ...value }
        next[key] = []
      }
      continue
    }
    const r = stripSubAgentToolResults(raw)
    if (r !== UNCHANGED) {
      next ??= { ...value }
      next[key] = r
    }
  }
  return next ?? UNCHANGED
}

function stripFromMessages(
  messages: MastraDBMessage[],
): MastraDBMessage[] | Unchanged {
  let changed = false
  const next: MastraDBMessage[] = new Array(messages.length)
  for (let i = 0; i < messages.length; i++) {
    const msg = messages[i]
    const newContent = stripSubAgentToolResults(msg.content)
    if (newContent === UNCHANGED) {
      next[i] = msg
    } else {
      next[i] = { ...msg, content: newContent as MastraDBMessage['content'] }
      changed = true
    }
  }
  return changed ? next : UNCHANGED
}

export class StripSubAgentToolResultsFromContextProcessor
  implements Processor<typeof PROCESSOR_ID>
{
  readonly id = PROCESSOR_ID

  processInput({
    messages,
    systemMessages,
  }: ProcessInputArgs): ProcessInputResult {
    const next = stripFromMessages(messages)
    return next === UNCHANGED
      ? { messages, systemMessages }
      : { messages: next, systemMessages }
  }

  processInputStep({
    messages,
  }: ProcessInputStepArgs): ProcessInputStepResult | undefined {
    const next = stripFromMessages(messages)
    if (next === UNCHANGED) return undefined
    return { messages: next }
  }
}
```

You can skip walking over messages of all types, and only consider messages of type `tool` (as sub-agents are also tools)

