import fs from 'fs'
import path from 'path'
import { fileURLToPath } from 'url'
import { OpenAPIRegistry, OpenApiGeneratorV31, extendZodWithOpenApi } from '@asteasolutions/zod-to-openapi'
import { z } from 'zod'
import { myHandler } from '../handlers'
import { responseZodSchema, errorZodSchema } from '../schemas'

// Extend Zod with OpenAPI capabilities
extendZodWithOpenApi(z)

const __filename = fileURLToPath(import.meta.url)
const __dirname = path.dirname(__filename)

const registry = new OpenAPIRegistry()

// Type for HTTP methods that matches OpenAPI spec
type HttpMethod = 'get' | 'post' | 'put' | 'delete' | 'patch' | 'options' | 'head' | 'trace'

registry.registerPath({
  method: myHandler.method.toLowerCase() as HttpMethod,
  path: myHandler.path,
  summary: 'My endpoint to do something',
  tags: ['my-tag'],
  request: {},
  responses: {
    200: {
      description: 'Successful response',
      content: {
        'application/json': {
          schema: responseZodSchema,
        },
      },
    },
    404: {
      description: 'Not found',
      content: {
        'application/json': {
          schema: errorZodSchema,
        },
      },
    },
  },
})


async function main(): Promise<void> {
  const generator = new OpenApiGeneratorV31(registry.definitions)

  const spec = generator.generateDocument({
    openapi: '3.1.0',
    info: {
      title: '....',
