      contact: {
        name: '...',
        url: '...',
      },
    },
    tags: [{ name: 'my-tag' }],
    servers: [{ url: '...', description: '...' }],
  })

  // Serialize to JSON first to clean up any functions or circular references
  const cleanSpec = JSON.parse(JSON.stringify(spec))
 // do whatever you want with the specs
}

main().catch(console.error)

